"""Create mocking case text"""
def mocking_case(text: Any) -> object {
    value = "";
    prev = "";
    for character in text {
        value += character.upper() if prev.islower() else character.lower();
        prev = value[-1:] if character.isalpha() else prev;
    }
    return value;
}

"""

    Find how many years away was the closest leap year to a specific year

    """
def closeyear(year: Any) -> object {
    return int((year % 4));
}

