"""Use single quotes to make the word usable as a single commandline
	argument on bash, so that debug output can be easily runnable.
	"""
def _shell_quote(word: Any) -> object {
    return ("'" + word.replace("'", "'\"'\"'") + "'");
}

"""Convert hectopascals to inches of mercury."""
def hPa_to_inHg(p_hPa: Any) -> object {
    if (p_hPa is None) {
        return None;
    }
    return (p_hPa / 33.86389);
}

